source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    totals = {}
    for row in grid:
        for value in row:
            totals[value] = totals.get(value, 0) + 1
    background = max(totals, key=totals.get)
    divider = next(r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != background)
    divider_color = grid[divider][0]
    counts = {}
    for r, row in enumerate(grid):
        if r == divider:
            continue
        for value in row:
            if value != background:
                counts[value] = counts.get(value, 0) + 1
    foreground = max(counts, key=counts.get)
    coords = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == foreground]
    top = min(r for r, c in coords)
    bottom = max(r for r, c in coords)
    if bottom < divider:
        dr = divider - 1 - bottom
        for r, c in coords:
            out[r][c] = background
            out[r + dr][c] = foreground
        line = top + dr - 1
    else:
        dr = divider + 1 - top
        for r, c in coords:
            out[r][c] = background
            out[r + dr][c] = foreground
        line = bottom + dr + 1
    if 0 <= line < h:
        out[line] = [8] * w
    return out
'''
